// Translates provider-agnostic operations into concrete HTTP requests.
// Supported ops: noop | get_record | update_record | log_activity | search_activities
// A call must contain ONE kind of op (so outputs stay index-aligned with inputs).
const cfg = $('Load config').first().json.crm;
const F = cfg.fields;
const base = cfg.base_url.replace(/\/$/, '');
const items = $('Start').all().map(i => i.json);

const ops = new Set(items.map(i => i.op));
if (ops.size > 1) throw new Error(`CRM adapter received mixed ops (${[...ops].join(', ')}). Send one op per call.`);
if (items.filter(i => i.op === 'search_activities').length > 1)
  throw new Error('search_activities: send one search per call (use Execute Workflow mode "each").');

// Zoho search criteria need ( ) , escaped
const zEsc = v => String(v).replace(/([(),\\])/g, '\\$1');
const zTime = iso => DateTime.fromISO(iso).toUTC().toFormat("yyyy-MM-dd'T'HH:mm:ss'+00:00'");

function build({ op, payload = {} }) {
  const r = { op, method: 'GET', url: '', qs: {}, body: null, kind: 'read' };
  const p = cfg.provider;

  if (op === 'noop') return { ...r, kind: 'skip' };

  if (op === 'get_record') {
    if (p === 'zoho')    return { ...r, url: `${base}/crm/v8/${cfg.contact_module}/${payload.id}`, qs: { fields: (payload.fields || []).join(',') } };
    if (p === 'hubspot') return { ...r, url: `${base}/crm/v3/objects/contacts/${payload.id}`, qs: { properties: (payload.fields || []).join(',') } };
    return { ...r, url: `${base}/contacts/${payload.id}`, qs: { fields: (payload.fields || []).join(',') } };
  }

  if (op === 'update_record') {
    const w = { ...r, kind: 'write' };
    if (p === 'zoho')    return { ...w, method: 'PUT',   url: `${base}/crm/v8/${cfg.contact_module}/${payload.id}`, body: { data: [payload.fields] } };
    if (p === 'hubspot') return { ...w, method: 'PATCH', url: `${base}/crm/v3/objects/contacts/${payload.id}`, body: { properties: payload.fields } };
    return { ...w, method: 'PATCH', url: `${base}/contacts/${payload.id}`, body: payload.fields };
  }

  if (op === 'log_activity') {
    const a = payload; const w = { ...r, kind: 'write', method: 'POST' };
    if (p === 'zoho') return { ...w, url: `${base}/crm/v8/${cfg.activity_module}`, body: { data: [{
      $se_module: cfg.contact_module,
      [cfg.link_field]: a.contact_id,
      Subject: a.run_name,
      Call_Type: 'Outbound',
      Outgoing_Call_Status: 'Completed',
      Call_Start_Time: zTime(a.started_at),
      Call_Duration: String(a.duration_secs ?? 0),
      [F.outcome]: a.outcome_label,
      [F.summary]: (a.summary || '').slice(0, 2000),
      Description: a.note,
    }] } };
    if (p === 'hubspot') return { ...w, url: `${base}/crm/v3/objects/calls`, body: {
      properties: {
        hs_timestamp: a.started_at, hs_call_title: a.run_name, hs_call_body: a.note,
        hs_call_direction: 'OUTBOUND', hs_call_status: 'COMPLETED', hs_call_duration: String((a.duration_secs ?? 0) * 1000),
        [F.outcome]: a.outcome_label, [F.summary]: a.summary, [F.campaign_key]: a.campaign_key,
        [F.campaign_run]: a.run_name, [F.contact_ref]: a.contact_id,
      },
      associations: [{ to: { id: a.contact_id }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 194 }] }],
    } };
    return { ...w, url: `${base}/activities`, body: a };
  }

  if (op === 'search_activities') {
    // payload: { run_name } for one run, or { subject_prefix, campaign_key, since } for a window
    const s = { ...r, kind: p === 'hubspot' ? 'search_cursor' : 'search_page' };
    if (p === 'zoho') {
      const criteria = payload.run_name
        ? `(Subject:equals:${zEsc(payload.run_name)})`
        : `((Subject:starts_with:${zEsc(payload.subject_prefix)})and(Call_Start_Time:greater_equal:${zTime(payload.since)}))`;
      return { ...s, url: `${base}/crm/v8/${cfg.activity_module}/search`,
        qs: { criteria, fields: [cfg.link_field, 'Subject', F.outcome, 'Call_Start_Time'].join(','), per_page: 200, page: 1 } };
    }
    if (p === 'hubspot') {
      const filters = payload.run_name
        ? [{ propertyName: F.campaign_run, operator: 'EQ', value: payload.run_name }]
        : [{ propertyName: F.campaign_key, operator: 'EQ', value: payload.campaign_key },
           { propertyName: 'hs_timestamp', operator: 'GTE', value: String(DateTime.fromISO(payload.since).toMillis()) }];
      return { ...s, method: 'POST', url: `${base}/crm/v3/objects/calls/search`,
        body: { filterGroups: [{ filters }], properties: [F.outcome, F.campaign_run, F.contact_ref, 'hs_timestamp'], limit: 100 } };
    }
    return { ...s, url: `${base}/activities`, qs: { ...payload, page: 1 } };
  }

  throw new Error(`Unknown CRM op "${op}"`);
}

return items.map(i => ({ json: build(i) }));

// Normalizes single-record responses (reads and writes) into { ok, status_code, id, fields, error }.
const provider = $('Load config').first().json.crm.provider;
return $input.all().map(({ json: res }) => {
  const code = res.statusCode ?? 0;
  const body = res.body ?? {};
  let ok = code >= 200 && code < 300;
  let id = null, fields = {}, error = null;

  if (provider === 'zoho') {
    const row = Array.isArray(body.data) ? body.data[0] : null;
    if (row?.status && row.status !== 'success') { ok = false; error = row.message || row.code; }
    id = row?.details?.id ?? row?.id ?? null;
    fields = row && !row.details ? row : {};
  } else if (provider === 'hubspot') {
    id = body.id ?? null; fields = body.properties ?? {};
  } else {
    id = body.id ?? null; fields = body.fields ?? body;
  }
  if (!ok && !error) error = body.message || body.error || `HTTP ${code}`;
  return { json: { ok, status_code: code, id, fields, error } };
});

// Flattens every page of a paginated search into one list of canonical activities.
const cfg = $('Load config').first().json.crm;
const F = cfg.fields;
const pages = $input.all().map(i => i.json).filter(p => p && Object.keys(p).length);

const activities = pages.flatMap(page => {
  if (cfg.provider === 'hubspot') return (page.results || []).map(r => ({
    id: r.id, contact_id: r.properties?.[F.contact_ref] ?? null, run_name: r.properties?.[F.campaign_run] ?? '',
    outcome: r.properties?.[F.outcome] ?? null, started_at: r.properties?.hs_timestamp ?? null,
  }));
  return (page.data || []).map(r => ({
    id: r.id,
    contact_id: typeof r[cfg.link_field] === 'object' ? r[cfg.link_field]?.id : (r[cfg.link_field] ?? r.contact_id ?? null),
    run_name: r.Subject ?? r.run_name ?? '',
    outcome: r[F.outcome] ?? r.outcome ?? null,
    started_at: r.Call_Start_Time ?? r.started_at ?? null,
  }));
});

return [{ json: { ok: true, count: activities.length, activities } }];
